 const depths=new Map();function depth(g,visiting=new Set()){if(depths.has(g))return depths.get(g);if(visiting.has(g))return 0;const recipe=model.goods.get(g)?.recipes?.[0],n=recipe?1+Math.max(0,...Object.keys(recipe).map(id=>depth(+id,new Set([...visiting,g])))):0;depths.set(g,n);return n;}for(const j of jobs)j.depth=depth(j.good);jobs.sort((a,b)=>a.depth-b.depth||a.good-b.good);
 const demands=new Map(),scale=model.edits.cycleDays/30;
 for(const n of nodes.values()){const b=n.city,pop=n.population+(b?seasonalVisitors(b,state.cycle,model.edits.cycleDays):0),s=pop/1000*scale;demands.set(n.id,{food:s*model.edits.foodPer1000,utilities:s*.1,construction:s*.04,military:s*(b&&(b.citadel||b.settlementClass?.startsWith('Forte'))?.12:.025)*(b?.i===25&&Math.floor(start/90)%2===0?1.25:1),luxury:s*(b?.capital||b?.magicSchool?.06:.025),research:s*(b?.magicSchool?.08:b?.capital?.005:.001),fleet:b?.majorPort?s*.03:0,inlandFleet:[3,13,120,191].includes(b?.i)?s*.04:0});demands.get(n.id).armor=(demands.get(n.id).military||0)*.35;last.demand[n.id]={};}
