  const classWeights={peasant:1,modest:1.2,comfortable:1.6,wealthy:2,aristocratic:2.5};demands.get(n.id).utilities=n.household.classes.reduce((v,r)=>v+r.residents*classWeights[r.id],0)/1000*scale*.1;
